  // Tool result payload. Replace ROWS with data injected by the MCP host if desired.
  const ROWS = [
    { name: "Ava Chen",        email: "ava.chen@acme.io",       role: "Engineer",  status: "active",   signups: 142, joined: "2025-01-14" },
    { name: "Liam Park",       email: "liam.park@acme.io",      role: "Designer",  status: "pending",  signups: 38,  joined: "2025-03-02" },
