    { name: "Sofia Alvarez",   email: "sofia.a@acme.io",        role: "Designer",  status: "active",   signups: 118, joined: "2024-12-09" },
    { name: "Omar Haddad",     email: "omar.h@acme.io",         role: "Analyst",   status: "inactive", signups: 12,  joined: "2025-07-22" },
    { name: "Priya Nair",      email: "priya.n@acme.io",        role: "Manager",   status: "active",   signups: 203, joined: "2025-01-30" },
    { name: "Tom Becker",      email: "tom.becker@acme.io",     role: "Engineer",  status: "pending",  signups: 47,  joined: "2025-04-18" }
  ];

  const tbody = document.getElementById("tbody");
  const q = document.getElementById("q");
  const statusFilter = document.getElementById("statusFilter");
  const roleFilter = document.getElementById("roleFilter");
  const shownEl = document.getElementById("shown");
  const totalEl = document.getElementById("total");
  const sortLabel = document.getElementById("sortLabel");
  const headers = [...document.querySelectorAll("thead th")];

  let sortKey = "name";
  let sortDir = 1; // 1 asc, -1 desc

  // Populate role filter dynamically
  [...new Set(ROWS.map(r => r.role))].sort().forEach(role => {
    const o = document.createElement("option");
    o.value = role; o.textContent = role;
    roleFilter.appendChild(o);
  });

  totalEl.textContent = ROWS.length;

  const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
  const fmtDate = d => new Date(d + "T00:00:00").toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });

  function apply() {
    const term = q.value.trim().toLowerCase();
    const st = statusFilter.value;
    const role = roleFilter.value;

    let rows = ROWS.filter(r => {
      if (st && r.status !== st) return false;
      if (role && r.role !== role) return false;
      if (term && !(`${r.name} ${r.email} ${r.role}`.toLowerCase().includes(term))) return false;
      return true;
    });

    rows.sort((a, b) => {
      let x = a[sortKey], y = b[sortKey];
      if (typeof x === "number" && typeof y === "number") return (x - y) * sortDir;
      return String(x).localeCompare(String(y)) * sortDir;
    });

    render(rows);
    shownEl.textContent = rows.length;
    sortLabel.textContent = `Sorted by ${sortKey} ${sortDir === 1 ? "↑" : "↓"}`;
  }

  function render(rows) {
    if (!rows.length) {
      tbody.innerHTML = `<tr><td class="empty" colspan="6">No matching rows.</td></tr>`;
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr>
        <td>${esc(r.name)}</td>
        <td>${esc(r.email)}</td>
        <td>${esc(r.role)}</td>
        <td><span class="status ${esc(r.status)}">${esc(r.status)}</span></td>
